void __stdcall Draw_EquipmentNeedToRepairBody() {
    // Static local variables (originally global data)
    static int gaBodySlotLocTable[7] = { 0x1, 0x3, 0x8, 0x9, 0xa, 0x4, 0x5 }; D2_STATIC_GUARD(gaBodySlotLocTable, "D2Client::UI::Panel::Draw_EquipmentNeedToRepairBody::gaBodySlotLocTable");

    uint32_t bHasDurability;
    BOOL BVar1;
    int32_t nMaxDurability;
    int nBodyLoc;
    uint32_t* pSlotLocEntry2;
    uint32_t bIsShield;
    int32_t bIsQuiver;
    int32_t nRepairState;
    D2UnitStrc* pItem = UNIT::Player::GetPlayerUnit_UI();
    D2InventoryStrc* pInventory = pItem->pInventory;
    int* pSlotLocEntry = gaBodySlotLocTable;
    do {
      pItem = D2Common::INVENTORY::Inventory::INVENTORY_GetItemByGridOffset(pInventory, *pSlotLocEntry);
      if (pItem) {
        bHasDurability = D2Common::ITEMS::Items::ITEM_CheckIfItemHasDurability(pItem);
        if (bHasDurability) {
          BVar1 = D2Common::ITEMS::Items::IsStackable(pItem);
          if (!BVar1) {
            nMaxDurability = D2Common::Stats::StatsEx::GetTxtMaxDurability(pItem);
            if (nMaxDurability) {
              nBodyLoc = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pItem, UNITSTAT_durability, 0);
              if (nBodyLoc * 100 / nMaxDurability <= 0x14) {
                pSlotLocEntry2 = (uint32_t*)gaBodySlotLocTable;
                break;
              }
            }
          }
        }
      }

      pSlotLocEntry++;
      if ((int)pSlotLocEntry >= (intptr_t)((char*)&gaBodySlotLocTable + sizeof(gaBodySlotLocTable))) {
        return;
      }
    } while (true);

    while (true) {
      eD2BodyLocDWORD eEquipSlot;
      eEquipSlot = *pSlotLocEntry2;
      pItem = D2Common::INVENTORY::Inventory::INVENTORY_GetItemByGridOffset(pInventory, eEquipSlot);
      nRepairState = 0;
      bIsShield = 0;
      bIsQuiver = 0;
      if (pItem) {
        bHasDurability = D2Common::ITEMS::Items::ITEM_CheckIfItemHasDurability(pItem);
        if (bHasDurability) {
          BVar1 = D2Common::ITEMS::Items::IsStackable(pItem);
          if (!BVar1) {
            nMaxDurability = D2Common::Stats::StatsEx::GetTxtMaxDurability(pItem);
            bIsShield = D2Common::ITEMS::Items::ITEMS_IsA(pItem, ITEMTYPE_AnyShield);
            bIsQuiver = D2Common::ITEMS::Items::ITEM_GetTxtItemTypes_quiver(pItem);
            if (nMaxDurability) {
              nBodyLoc = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pItem, UNITSTAT_durability, 0);
              nBodyLoc = nBodyLoc * 100 / nMaxDurability;
              if (nBodyLoc <= 0) {
                nRepairState = 2;
              } else if (nBodyLoc <= 0x14) {
                nRepairState = 1;
              }
            }
          }
        }

        Draw_EquipmentNeedToRepairBody_1(bIsQuiver, bIsShield, eEquipSlot, nRepairState);
      } else {
        if (eEquipSlot != BODYLOC_R_ARM && eEquipSlot != BODYLOC_L_ARM) {
          Draw_EquipmentNeedToRepairBody_1(bIsQuiver, bIsShield, eEquipSlot, nRepairState);
        }
      }

      pSlotLocEntry2++;
      if ((int)pSlotLocEntry2 >= (intptr_t)((char*)&gaBodySlotLocTable + sizeof(gaBodySlotLocTable))) {
        return;
      }
    }
}

void __stdcall PANEL_DrawPanelLayout() {
    int32_t nTextWidth;
    int nClearCount;
    int32_t nStatValue;
    uint16_t wszMpFormatted[100];
    uint16_t wszHpFormatted[100];
    uint16_t wszMpText[100];
    uint16_t wszHpText[100];
    D2UnitStrc* pUnit = UNIT::Player::GetPlayerUnit_UI();
    int nMouseX = ui::GetMouseX();
    int nMouseXSaved = nMouseX;
    int nMouseY = ui::GetMouseY();
    for (nClearCount = 0; nClearCount < 0x64; nClearCount++) {
      wszHpText[nClearCount] = L'\0';
    }

    for (nClearCount = 0; nClearCount < 0x64; nClearCount++) {
      wszMpText[nClearCount] = L'\0';
    }

    for (nClearCount = 0; nClearCount < 0x64; nClearCount++) {
      wszHpFormatted[nClearCount] = L'\0';
    }

    uint16_t* pwszBuf = wszMpFormatted;
    int nMouseYSaved = nMouseY;
    for (nClearCount = 0x32; nClearCount; nClearCount--) {
      pwszBuf[0] = L'\0';
      pwszBuf[1] = L'\0';
      pwszBuf += 2;
    }

    if (bShowHpText || nMouseX - 0x1eU <= 0x50 && nMouseY >= ScreenSizeY - 0x4b && nMouseY <= ScreenSizeY - 0xf) {
      D2UnitStrc* pPlayerUnit_lcl;
      nTextWidth = PANEL_GetSmoothedStatValue(UNITSTAT_hitpoints);
      nStatValue = nTextWidth >> 8;
      nTextWidth = D2Common::Stats::StatsEx::GetTxtMaxHp(pUnit);
      nMouseY = nTextWidth >> 8;
      pPlayerUnit_lcl = UNIT::Player::GetPlayerUnit_UI();
      if (pPlayerUnit_lcl && pPlayerUnit_lcl->eUnitType == UNIT_PLAYER && pPlayerUnit_lcl->eAnimMode.ePlayerMode != eD2PlayerAnimMode_ns::Dead && (uint32_t)nStatValue <= 1) {
        nStatValue = 1;
      }

      D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(100, wszHpFormatted, D2Lang::StrTable::strtable::GetLocaleString(0x1045), nStatValue, nMouseY);
      D2Lang::Unicode::UNISYS::AppendToBuffer(wszHpText, wszHpFormatted);
      nTextWidth = D2Win::Src::D2WinFont::DRAW_text0(wszHpText);
      D2Win::Src::D2WinFont::DRAW_text(wszHpText, 0x41 - nTextWidth / 2, ScreenSizeY - 0x5f, 0, 0);
      nMouseY = nMouseYSaved;
      nMouseX = nMouseXSaved;
    }
    if (!(bShowmpText || nMouseX >= ScreenSizeX - 0x6f && nMouseX <= ScreenSizeX - 0x1f && nMouseY >= ScreenSizeY - 0x4b && nMouseY <= ScreenSizeY - 0xf)) {
      return;
    }

    nTextWidth = PANEL_GetSmoothedStatValue(UNITSTAT_mana);
    nMouseX = nTextWidth >> 8;
    nTextWidth = D2Common::Stats::StatsEx::GetTxtMaxMana(pUnit);
    nMouseY = nTextWidth >> 8;
    D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(100, wszMpFormatted, D2Lang::StrTable::strtable::GetLocaleString(0x1046), nMouseX, nMouseY);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszMpText, wszMpFormatted);
    nTextWidth = D2Win::Src::D2WinFont::DRAW_text0(wszMpText);
    D2Win::Src::D2WinFont::DRAW_text(wszMpText, ScreenSizeX - nTextWidth / 2 - 0x50, ScreenSizeY - 0x5f, 0, 0);
}

